SELECT COUNT(DISTINCT a.hadm_id) AS num_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'F' AND p.anchor_age = 90 AND p.insurance = 'Medicare' AND p.anchor_year BETWEEN 85 AND 95 AND t.eventtype = 'Transfer' AND d.icd_code = 'Osteomyelitis' AND a.admission_type = 'Index';